const fs = require('fs');
const path = require('path');

const now = new Date();
const year = now.getFullYear();
const month = String(now.getMonth() + 1).padStart(2, '0');
const day = String(now.getDate()).padStart(2, '0');
const date = `${year}-${month}-${day}`;
const dow = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][now.getDay()];
const isWeekday = !['Saturday','Sunday'].includes(dow);

const PERSONAL_DIR = '/mnt/nas/Obsidian/Personal/Daily';
const WORK_DIR = '/mnt/nas/Obsidian/Work/Daily';

const results = [];

// Personal daily note — every day
const personalPath = path.join(PERSONAL_DIR, `${date}.md`);
if (!fs.existsSync(personalPath)) {
  fs.mkdirSync(PERSONAL_DIR, { recursive: true });
  const content = `---
title: Daily — ${date}
date: ${date}
type: daily
tags:
  - daily
  - reflection
---

# Daily — ${date}

## Most Important Thing


## Urgent


## Maintenance


## Gratitude


## Worth Noting
`;
  fs.writeFileSync(personalPath, content);
  results.push({ vault: 'Personal', file: `${date}.md`, status: 'created' });
} else {
  results.push({ vault: 'Personal', file: `${date}.md`, status: 'exists' });
}

// Work daily note — weekdays only
if (isWeekday) {
  const workPath = path.join(WORK_DIR, `${date}.md`);
  if (!fs.existsSync(workPath)) {
    fs.mkdirSync(WORK_DIR, { recursive: true });
    const content = `---
title: Work — ${date}
date: ${date}
type: daily
tags:
  - daily
  - work
---

# Work — ${date}

## Most Important Thing


## Urgent


## Maintenance


## Worth Noting
`;
    fs.writeFileSync(workPath, content);
    results.push({ vault: 'Work', file: `${date}.md`, status: 'created' });
  } else {
    results.push({ vault: 'Work', file: `${date}.md`, status: 'exists' });
  }
}

return results.map(r => ({ json: r }));
